<?php

declare(strict_types=1);

namespace OCA\Groceries\Service;

/**
 * The built-in item catalog (lib/Catalog/catalog.json, generated by scripts/build-catalog.mjs).
 * Matching logic is mirrored in src/lib/catalog.ts.
 */
class CatalogService {
	/** @var array{version:string,categories:list<array>,items:list<array>}|null */
	private ?array $data = null;
	/** @var array<string,string> normalized term => item key */
	private array $index = [];
	/** @var array<string,array> */
	private array $items = [];
	/** @var array<string,array> */
	private array $categories = [];
	private string $file;

	public function __construct() {
		$this->file = __DIR__ . '/../Catalog/catalog.json';
	}

	private function load(): void {
		if ($this->data !== null) {
			return;
		}
		$json = file_get_contents($this->file);
		$data = $json === false ? null : json_decode($json, true);
		if (!is_array($data)) {
			$data = ['version' => '0', 'categories' => [], 'items' => []];
		}
		$this->data = $data;
		foreach ($data['categories'] as $c) {
			$this->categories[$c['key']] = $c;
		}
		foreach ($data['items'] as $item) {
			$this->items[$item['key']] = $item;
		}
		// names take precedence over synonyms; first item wins
		foreach ($data['items'] as $item) {
			foreach ($item['names'] as $name) {
				$this->index[NameNormalizer::normalize($name)] ??= $item['key'];
			}
		}
		foreach ($data['items'] as $item) {
			foreach ($item['synonyms'] ?? [] as $terms) {
				foreach ($terms as $term) {
					$this->index[NameNormalizer::normalize($term)] ??= $item['key'];
				}
			}
		}
	}

	public function getVersion(): string {
		$this->load();
		return (string)$this->data['version'];
	}

	/** @return array{version:string,categories:list<array>,items:list<array>} */
	public function getData(): array {
		$this->load();
		return $this->data;
	}

	public function getItem(string $key): ?array {
		$this->load();
		return $this->items[$key] ?? null;
	}

	public function getCategory(string $key): ?array {
		$this->load();
		return $this->categories[$key] ?? null;
	}

	/** @return list<string> all category keys in default aisle order */
	public function getCategoryKeys(): array {
		$this->load();
		return array_keys($this->categories);
	}

	/** The category set a list template uses: grocery (also for "custom" lists), pharmacy or hardware. */
	public static function listType(string $template): string {
		return in_array($template, ['pharmacy', 'hardware'], true) ? $template : 'grocery';
	}

	/** @return list<string> the categories of one list type, in default aisle order */
	public function getCategoryKeysFor(string $template): array {
		$this->load();
		$type = self::listType($template);
		return array_values(array_keys(array_filter($this->categories, fn ($c) => $c['template'] === $type || $c['template'] === 'all')));
	}

	public function isCategoryFor(string $key, string $template): bool {
		$this->load();
		$c = $this->categories[$key] ?? null;
		return $c !== null && ($c['template'] === 'all' || $c['template'] === self::listType($template));
	}

	/** Category of a catalog item on a list of the given template ("other" when that list type has none). */
	public function itemCategory(array $item, string $template): string {
		$type = self::listType($template);
		return $type === 'grocery' ? $item['category'] : ($item['types'][$type] ?? 'other');
	}

	/**
	 * Finds the catalog item for a free-text name.
	 * "exact" is true when the whole name (or its singular/plural form) is a known name or synonym;
	 * a non-exact match was found on the trailing words only ("frische Bio-Tomaten" -> tomatoes).
	 *
	 * @return array{item: array, exact: bool}|null
	 */
	public function match(string $name): ?array {
		$this->load();
		$norm = NameNormalizer::normalize($name);
		if ($norm === '') {
			return null;
		}
		$key = $this->lookup($norm);
		if ($key !== null) {
			return ['item' => $this->items[$key], 'exact' => true];
		}
		$words = explode(' ', $norm);
		for ($i = 1; $i < count($words); $i++) {
			$key = $this->lookup(implode(' ', array_slice($words, $i)));
			if ($key !== null) {
				return ['item' => $this->items[$key], 'exact' => false];
			}
		}
		// German compounds: "Bio Vollmilchjoghurt" -> "...joghurt" (only longer tails to avoid noise)
		$last = $words[count($words) - 1];
		if (mb_strlen($last) > 6) {
			for ($i = 1; $i <= mb_strlen($last) - 4; $i++) {
				$key = $this->index[mb_substr($last, $i)] ?? null;
				if ($key !== null) {
					return ['item' => $this->items[$key], 'exact' => false];
				}
			}
		}
		return null;
	}

	private function lookup(string $norm): ?string {
		foreach (NameNormalizer::variants($norm) as $v) {
			if (isset($this->index[$v])) {
				return $this->index[$v];
			}
		}
		return null;
	}
}
